import{_ as o,l,o as a,c as p,v as r,p as s,x as t,d as i,i as h,S as u}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"per-tensor / channel / group","description":"","frontmatter":{"title":"per-tensor / channel / group","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/quant-granularity.md","filePath":"llm/quant-granularity.md","lastUpdated":1789023840000}'),d={name:"llm/quant-granularity.md"};function c(g,e,m,E,_,A){const n=l("Mermaid");return a(),p("div",null,[e[1]||(e[1]=r('<h1 id="per-tensor-channel-group" tabindex="-1">per-tensor / channel / group <a class="header-anchor" href="#per-tensor-channel-group" aria-label="Permalink to &quot;per-tensor / channel / group&quot;">​</a></h1><div class="epigraph"><p>尺度共享的范围越大，元数据越少、核越简单、离群越能绑架整张量。粒度是在「一个 $s$ 管多少个数」上买精度。</p><footer>—— 对照 per-tensor INT8 与 GPTQ / AWQ 的分组尺度</footer></div><p><a href="/llm/symmetric-asymmetric-quant">上一课</a> 决定格子滑不滑动。本课决定 <strong>同一套 \\((s,z)\\) 覆盖多大一块</strong>。缺口是粒度：per-tensor、per-channel（通常沿输出通道）、per-group（沿输入通道每 \\(g\\) 个）。<a href="/llm/gptq">GPTQ</a> 常用 \\(g=128\\) 一类分组；AWQ 保护通道也是通道维上的尺度。不要重讲 Hessian，只补共享范围如何与<a href="/llm/why-activation-outliers">离群</a> 相互作用。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Per-tensor：一层一个 \\(s\\)。核最简单，离群一个数就拉开整层格子，其余权重挤在零附近。Per-channel：每个输出通道一个 \\(s\\)，匹配「某行权重很大」的结构，INT8 通道尺度是成熟路径。Per-group：把一行再切成组，组内共享 \\(s\\)，逼近逐元素尺度，元数据按 \\(1/g\\) 增长，核要按组反量化。</p><p>\\(g\\) 太小：每参数比特被 scale 吃掉，带宽红利消失。\\(g\\) 太大：组内仍可能有离群。问题是 <strong>误差与元数据与核实现三方同时可行的 \\(g\\)</strong>，不是越小越先进。</p><p><span class="marginnote">「逐 token」激活量化是另一维粒度，服务上 KV 与激活常 per-token 尺度。本课主线先盯权重；激活粒度在校准课会碰头。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>权重 PTQ：从 per-channel 起，4-bit 不够再降到 group。GPTQ / AWQ 的公开实现把 group size 当检查点字段，换 \\(g\\) 必须重跑量化，不能只改推理配置。lm_head、embed 常留更高精度或更细粒度，因为误差直接进 logits。</p><p>激活：per-tensor 几乎只在无离群时能 W8A8；SmoothQuant 把难度推到权重通道尺度上，使激活能 per-tensor 或粗粒度。否则 per-channel / per-token。</p>',10)),(a(),s(u,null,{default:t(()=>[h(n,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22per-tensor%22%5D%20--%3E%20CHEAP%5B%22%E6%A0%B8%E7%AE%80%E5%8D%95%2C%20%E7%A6%BB%E7%BE%A4%E7%BB%91%E6%9E%B6%22%5D%0A%20%20C%5B%22per-channel%22%5D%20--%3E%20ROW%5B%22%E4%B8%80%E8%A1%8C%E4%B8%80%E4%B8%AA%20s%22%5D%0A%20%20G%5B%22per-group%22%5D%20--%3E%20META%5B%22%E5%85%83%E6%95%B0%E6%8D%AE%20x%201%2Fg%22%5D%0A%20%20G%20--%3E%20ERR%5B%22%E7%BB%84%E5%86%85%E4%BB%8D%E5%8F%AF%E6%9C%89%E9%92%89%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[i(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<p>存储布局必须与核一致：group 沿哪一维切、是否 packed INT4，是契约。错维等于错尺度，质量崩了还以为是校准问题。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>离群若沿通道对齐，per-channel 几乎消灭绑架；若离群在通道内部稀疏几个元素，只有细 group 或非均匀/混精能救。激活离群沿 hidden 维对齐时，权重侧 group 帮不上激活格子，要平滑或混精。粒度选择其实是在猜离群的轴——先测直方图的轴，再选 \\(g\\)。</p><p>GEMM 核按 tile 吃数据。group 边界与 tile 不对齐会强制边界处理，吞吐掉档。所以 \\(g\\) 常取 64/128，不只是精度美学。</p><p><span class="marginnote">双重量化（QLoRA）是把 per-group 的 \\(s\\) 再量化，专治「\\(g\\) 小导致 scale 比特反弹」。它不改变 \\(W\\) 的网格几何。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要把论文的 \\(g=128\\) 当物理常数。不要在没有对应核时用 \\(g=4\\) 宣传每参数 4 bit——实际带宽按解包后算。不要对不同层用不同 \\(g\\) 却共用一个加载器。下一课校准集：这些 \\(s,z\\) 从哪些样本估出来。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>共享尺度的范围：张量 \\(\\lt\\) 通道 \\(\\lt\\) 组 \\(\\lt\\) 元素，精度升、元数据与核复杂度升。</li><li>离群轴决定哪一档粒度够用；先测再选 \\(g\\)。</li><li>GPTQ/AWQ 的 group size 是检查点契约。</li><li>\\(g\\) 还要对齐 GEMM tile，不只对齐误差。</li><li>出处：INT8 通道量化实践；GPTQ/AWQ 分组尺度。</li></ul>',9))])}const f=o(d,[["render",c]]);export{B as __pageData,f as default};
